// geoJSONClose compares two JSON documents, allowing numbers to differ by
// 1e-9 (last-digit noise between Go's and .NET's math libraries).
func geoJSONClose(a, b interface{}) bool {
	switch x := a.(type) {
	case float64:
		y, ok := b.(float64)
		return ok && math.Abs(x-y) <= 1e-9
	case []interface{}:
		y, ok := b.([]interface{})
		if !ok || len(x) != len(y) {
			return false
		}
		for i := range x {
			if !geoJSONClose(x[i], y[i]) {
				return false
			}
		}
		return true
	case map[string]interface{}:
		y, ok := b.(map[string]interface{})
		if !ok || len(x) != len(y) {
			return false
		}
		for k, v := range x {
			if !geoJSONClose(v, y[k]) {
				return false
			}
		}
		return true
	}
	return a == b
}

